<?php
namespace qqworld_collector\module; use qqworld_collector\lib; class database extends lib { var $options; var $module = 'database'; var $settings_name = 'qqworld-collector-database'; public function __construct() { if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; add_action( 'admin_menu', array($this, 'admin_menu') ); add_action( 'admin_init', array($this, 'register_settings') ); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_filter( 'wp_insert_post_data', array($this, 'wipe_content'), 10, 2 ); add_filter( 'qqworld-collector-database-iterate-over-array', array($this, 'iterate_over_array') ); add_action( 'wp_ajax_qqworld-collector-database-add-content', array($this, 'add_content') ); add_action( 'wp_ajax_nopriv_qqworld-collector-database-add-content', array($this, 'add_content') ); } public function wipe_content($data, $postarr) { if ( !in_array($data['post_status'], array('auto-draft', 'trash', 'inherit')) && filter_var($this->options->qc_database_wipe_content_enabled, FILTER_VALIDATE_BOOLEAN) ) { $patterns = array(); $replacements = array(); if ($this->options->qc_database_wipe_content_tags) { $tags = explode("\r\n", $this->options->qc_database_wipe_content_tags); foreach ($tags as $tag) { $patterns[] = '/<'.$tag.'\\b(?!\\w)([^>]*)>/i'; $replacements[] = ''; $patterns[] = '/<\/'.$tag.'>/i'; $replacements[] = ''; } } if ($this->options->qc_database_wipe_content_attributes) { $attributes = explode("\r\n", $this->options->qc_database_wipe_content_attributes); foreach ($attributes as $attribute) { $attribute = str_replace('*', '[^"]*?', $attribute); $patterns[] = '/ '.$attribute.'=\\\\"[^"]*?\\\\"/i'; $replacements[] = ''; } } $data['post_content'] = preg_replace($patterns, $replacements, $data['post_content']); if ($this->options->qc_database_wipe_tag_comment) { $data['post_content'] = preg_replace_callback('/<!--([\s\S]*?)-->/i', function($matches) { return $matches[1] == 'nextpage' ? $matches[0] : ''; }, $data['post_content']); } if ($this->options->qc_database_wipe_empty_tags) { $data['post_content'] = $this->wipe_empty_tags($data['post_content']); } } return $data; } public function admin_menu() { $parent_slug = 'qqworld-collector'; $page_title = __('Database', $this->text_domain); $menu_title = $page_title; $capability = !$this->options->qc_authorization_all_roles_can_modify_settings ? 'manage_options' : $this->options->qc_authorization_who_can_use; $menu_slug = 'qqworld-collector-database'; $function = array($this, 'database'); $settings_page = add_submenu_page($parent_slug, $page_title, $menu_title, $capability, $menu_slug, $function); add_action( "load-{$settings_page}", array($this, 'help_tab') ); } public function register_settings() { register_setting($this->settings_name, $this->settings_name); } public function database() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'database.php'; } public function admin_enqueue_scripts() { $screen = get_current_screen(); if (strstr($screen->id, 'qqworld-collector-database')) { wp_enqueue_style('animate'); wp_enqueue_script('noty'); wp_enqueue_style('noty'); wp_enqueue_script('jquery-effects-core'); wp_enqueue_script('jquery-effects-shake'); wp_enqueue_script('qqworld-collector-database-admin'); } } public function add_translation_array($translation_array) { $translation_array['text']['please_enter_source_replacement'] = __('Please enter Source Text.', $this->text_domain); $translation_array['text']['are_your_sure'] = __('Are you sure?<br />Before you click the yes button, I recommend backup site database.', $this->text_domain); $translation_array['database_activated'] = apply_filters( 'qqworld-collector-activated-module-database', false ); return $translation_array; } public function deep_replace($data){ if (empty($data)) { return $data; } return is_array($data) ? array_map(array($this, 'deep_replace'), $data) : str_replace($this->source, $this->replacement, $data); } public function iterate_over_array($results) { global $wpdb; $count = count($results['rows']); extract($results); $this->source = $source; $this->replacement = $replacement; if ($count) { foreach ($rows as $row) { if (is_serialized($row->meta_value)) { $meta_value = unserialize($row->meta_value); $meta_value = $this->deep_replace($meta_value); $meta_value = serialize($meta_value); $sql = "UPDATE `{$table}` SET `meta_value`='{$meta_value}' WHERE `meta_id` = {$row->meta_id}"; } else { $sql = "UPDATE `{$table}` SET `meta_value`=REPLACE(`meta_value`, '{$source}', '{$replacement}') WHERE `meta_id` = {$row->meta_id}"; } $result = $wpdb->query($sql); } } unset($results['rows']); $results['success'] = $count; $results['msg'] = $count ? sprintf(_n('%d data has been effected.', '%d data have been effected.', $count, $this->text_domain), $count) : __('Nothing Changed.', $this->text_domain); return $results; } public function add_content() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; global $wpdb; extract($_POST); if (isset($meta_value) && $meta_value) { for ($i=0; $i<1000; $i++) { $sql = "SELECT ID FROM `{$wpdb->posts}` a WHERE `post_type`='{$post_type}' AND `post_status`='publish' AND NOT EXISTS (SELECT * FROM `{$wpdb->postmeta}` b WHERE a.`ID`=b.`post_id` AND b.`meta_key`='{$meta_key}') LIMIT ".(1000*$i).",1000"; $posts = $wpdb->get_results($sql); if (count($posts)) { foreach ($posts as $post) { add_post_meta($post->ID, $meta_key, $meta_value); } } else { break; } } for ($i=0; $i<1000; $i++) { $sql = "SELECT ID FROM `{$wpdb->posts}` a WHERE `post_type`='{$post_type}' AND `post_status`='publish' AND EXISTS (SELECT * FROM `{$wpdb->postmeta}` b WHERE a.`ID`=b.`post_id` AND b.`meta_key`='{$meta_key}' AND b.`meta_value`<>'{$meta_value}') LIMIT ".(1000*$i).",1000"; $posts = $wpdb->get_results($sql); if (count($posts)) { foreach ($posts as $post) { update_post_meta($post->ID, $meta_key, $meta_value); } } else { break; } } $results = array( 'success' => 1, 'msg' => __('Successfully added content.', $this->text_domain) ); } else { $sql = "DELETE FROM `{$wpdb->postmeta}` WHERE `meta_key`='{$meta_key}'"; $wpdb->query($sql); $results = array( 'success' => 1, 'msg' => __('Successfully removed content.', $this->text_domain) ); } print json_encode($results); exit; } } ?>